export const dataProvider = (
  apiUrl: string,
  httpClient: AxiosInstance = axiosInstance,
  options: SimpleRestOptions = {},
): Required<DataProvider> => ({
  getList: async ({ resource, pagination, filters, sorters, meta }) => {
    const url = `${apiUrl}/${resource}`;

    const {
      currentPage = 1,
      pageSize = 10,
      mode = "server",
    } = pagination ?? {};

    const { headers: headersFromMeta, method, signal } = meta ?? {};
    const requestMethod = (method as MethodTypes) ?? "get";

    const queryFilters = generateFilter(filters);

    const query: {
      _start?: number;
      _end?: number;
      _sort?: string;
      _order?: string;
      [param: string]: string | number | undefined;
    } = {};

    const {
      cursorParam = "cursor",
      limitParam = "limit",
      getCursor = defaultGetCursor,
    } = options.cursor ?? {};

    if (mode === "cursor") {
      if (pagination?.cursor !== undefined) {
        query[cursorParam] = pagination.cursor;
      }
      query[limitParam] = pageSize;
    } else if (mode === "server") {
      query._start = (currentPage - 1) * pageSize;
      query._end = currentPage * pageSize;
    }

    const generatedSort = generateSort(sorters);
    if (generatedSort) {
      const { _sort, _order } = generatedSort;
      query._sort = _sort.join(",");
      query._order = _order.join(",");
    }

    const combinedQuery = { ...query, ...queryFilters };
    const urlWithQuery = Object.keys(combinedQuery).length
      ? `${url}?${stringify(combinedQuery)}`
      : url;

    const { data, headers } = await httpClient[requestMethod](urlWithQuery, {
      headers: headersFromMeta,
      ...withSignal(signal),
    });

    if (mode === "cursor") {
      return {
        data,
        total: (headers?.["x-total-count"] === undefined
          ? undefined
          : getTotal(headers["x-total-count"], data)) as number,
        cursor: getCursor({ data, headers }),
      };
    }

    return {
      data,
      total: getTotal(headers?.["x-total-count"], data),
    };
  },

  getMany: async ({ resource, ids, meta }) => {
    const { headers, method, signal } = meta ?? {};
    const requestMethod = (method as MethodTypes) ?? "get";

    const { data } = await httpClient[requestMethod](
      `${apiUrl}/${resource}?${stringify({ id: ids })}`,
      { headers, ...withSignal(signal) },
    );

    return {
      data,
    };
  },

  create: async ({ resource, variables, meta }) => {
    const url = `${apiUrl}/${resource}`;

    const { headers, method } = meta ?? {};
    const requestMethod = (method as MethodTypesWithBody) ?? "post";

    const { data } = await httpClient[requestMethod](url, variables, {
      headers,
    });

    return {
      data,
    };
  },

  createMany: async ({ resource, variables, meta }) => {
    const url = `${apiUrl}/${resource}`;

    const { headers, method } = meta ?? {};
    const requestMethod = (method as MethodTypesWithBody) ?? "post";

    const responses = await Promise.all(
      variables.map((item) =>
        httpClient[requestMethod](url, item, {
          headers,
        }),
      ),
    );

    return {
      data: responses.map(({ data }) => data),
    };
  },

  update: async ({ resource, id, variables, meta }) => {
    const url = `${apiUrl}/${resource}/${id}`;

    const { headers, method } = meta ?? {};
    const requestMethod = (method as MethodTypesWithBody) ?? "patch";

    const { data } = await httpClient[requestMethod](url, variables, {
      headers,
    });

    return {
      data,
    };
  },

  updateMany: async ({ resource, ids, variables, meta }) => {
    const { headers, method } = meta ?? {};
    const requestMethod = (method as MethodTypesWithBody) ?? "patch";

    const responses = await Promise.all(
      ids.map((id) =>
        httpClient[requestMethod](`${apiUrl}/${resource}/${id}`, variables, {
          headers,
        }),
      ),
    );

    return {
      data: responses.map(({ data }) => data),
    };
  },

  getOne: async ({ resource, id, meta }) => {
    const url = `${apiUrl}/${resource}/${id}`;

    const { headers, method, signal } = meta ?? {};
    const requestMethod = (method as MethodTypes) ?? "get";

    const { data } = await httpClient[requestMethod](url, {
      headers,
      ...withSignal(signal),
    });

    return {
      data,
    };
  },

  deleteOne: async ({ resource, id, variables, meta }) => {
    const url = `${apiUrl}/${resource}/${id}`;

    const { headers, method } = meta ?? {};
    const requestMethod = (method as MethodTypesWithBody) ?? "delete";

    const { data } = await httpClient[requestMethod](url, {
      data: variables,
      headers,
    });

    return {
      data,
    };
  },

  deleteMany: async ({ resource, ids, variables, meta }) => {
    const { headers, method } = meta ?? {};
    const requestMethod = (method as MethodTypesWithBody) ?? "delete";

    const responses = await Promise.all(
      ids.map((id) =>
        httpClient[requestMethod](`${apiUrl}/${resource}/${id}`, {
          data: variables,
          headers,
        }),
      ),
    );

    return {
      data: responses.map(({ data }) => data),
    };
  },

  getApiUrl: () => {
    return apiUrl;
  },

  custom: async ({
    url,
    method,
    filters,
    sorters,
    payload,
    query,
    headers,
    meta,
  }) => {
    let requestUrl = `${url}?`;

    if (sorters) {
      const generatedSort = generateSort(sorters);
      if (generatedSort) {
        const { _sort, _order } = generatedSort;
        const sortQuery = {
          _sort: _sort.join(","),
          _order: _order.join(","),
        };
        requestUrl = `${requestUrl}&${stringify(sortQuery)}`;
      }
    }

    if (filters) {
      const filterQuery = generateFilter(filters);
      requestUrl = `${requestUrl}&${stringify(filterQuery)}`;
    }

    if (query) {
      requestUrl = `${requestUrl}&${stringify(query)}`;
    }

    let axiosResponse;
    switch (method) {
      case "put":
      case "post":
      case "patch":
        axiosResponse = await httpClient[method](url, payload, {
          headers,
        });
        break;
      case "delete":
        axiosResponse = await httpClient.delete(url, {
          data: payload,
          headers: headers,
        });
        break;
      default:
        axiosResponse = await httpClient.get(requestUrl, {
          headers,
          ...withSignal(meta?.signal),
        });
        break;
    }

    const { data } = axiosResponse;

    return Promise.resolve({ data });
  },
});
